// fayl: proxy.ts
import { NextResponse, type NextRequest } from "next/server"

export function proxy(request: NextRequest) {
  const theme = request.cookies.get("theme")?.value ?? "light"

  // 1) ichkariga: sahifa va handler headers() orqali o'qiydi
  const requestHeaders = new Headers(request.headers)
  requestHeaders.set("x-theme", theme)
  const response = NextResponse.next({ request: { headers: requestHeaders } })

  // 2) tashqariga: bu sarlavha va cookie brauzerga boradi
  response.headers.set("x-served-by", "proxy")
  response.cookies.set("last_visit", "2026-10-20", { path: "/", httpOnly: true })
  return response
}

