import { NextResponse, type NextRequest } from "next/server"

const locales = ["uz", "en", "ru"]

function detectLocale(request: NextRequest) {
  const saved = request.cookies.get("NEXT_LOCALE")?.value
  if (saved && locales.includes(saved)) return saved // foydalanuvchi o'zi tanlagan

  const lang = request.headers.get("accept-language")?.slice(0, 2)
  return lang && locales.includes(lang) ? lang : "uz"
}

export function proxy(request: NextRequest) {
  return NextResponse.redirect(new URL(`/${detectLocale(request)}`, request.url))
}

