const ratelimit = new Ratelimit({
  redis: Redis.fromEnv(), // UPSTASH_REDIS_REST_URL va UPSTASH_REDIS_REST_TOKEN
  limiter: Ratelimit.slidingWindow(3, "60 s"),
  prefix: "oshxona-api",
})

export async function proxy(request: NextRequest, event: NextFetchEvent) {
  const ip = request.headers.get("x-forwarded-for")?.split(",")[0].trim() ?? "local"
  const { success, limit, remaining, pending } = await ratelimit.limit(ip)
  event.waitUntil(pending) // fon sinxronlash javobni kutdirmaydi

  if (!success) {
    return NextResponse.json({ error: "Juda ko'p so'rov, keyinroq urining" }, { status: 429 })
  }
  const response = NextResponse.next()
  response.headers.set("X-RateLimit-Limit", String(limit))
  response.headers.set("X-RateLimit-Remaining", String(remaining))
  return response
}

