// fayl: proxy.ts
import { createHmac, timingSafeEqual } from "node:crypto"
import { NextResponse, type NextRequest } from "next/server"

function isValid(cookie: string | undefined) {
  if (!cookie) return false
  const [userId, signature = ""] = cookie.split(".")
  const expected = createHmac("sha256", process.env.COOKIE_SECRET ?? "").update(userId).digest("hex")
  return signature.length === expected.length && timingSafeEqual(Buffer.from(signature), Buffer.from(expected))
}

export function proxy(request: NextRequest) {
  if (!isValid(request.cookies.get("uid")?.value)) {
    return NextResponse.json({ error: "Imzo noto'g'ri" }, { status: 401 })
  }
}

