// fayl: app/lib/login-limit.ts
import "server-only"

const WINDOW = 15 * 60 * 1000
const MAX_FAILS = 5
const fails = new Map<string, { count: number; first: number }>()

export function isBlocked(key: string, now = Date.now()) {
  const entry = fails.get(key)
  if (!entry || now - entry.first > WINDOW) return false
  return entry.count >= MAX_FAILS
}

export function recordFail(key: string, now = Date.now()) {
  const entry = fails.get(key)
  if (!entry || now - entry.first > WINDOW) fails.set(key, { count: 1, first: now })
  else entry.count++
}

export function clearFails(key: string) {
  fails.delete(key)
}

