"use server"
import { redirect } from "next/navigation"
import { checkCredentials } from "@/app/lib/users"
import { createSession } from "@/app/lib/session"
import { clearFails, isBlocked, recordFail } from "@/app/lib/login-limit"

export async function login(_state: { message?: string } | undefined, formData: FormData) {
  const email = String(formData.get("email") ?? "").toLowerCase()
  const key = `login:${email}`
  if (isBlocked(key)) {
    return { message: "Juda ko'p urinish. 15 daqiqadan keyin qayta urining." }
  }
  const user = await checkCredentials(email, String(formData.get("password") ?? ""))
  if (!user) {
    recordFail(key)
    return { message: "Email yoki parol noto'g'ri." }
  }
  clearFails(key)
  await createSession(user.id)
  redirect("/dashboard")
}

