// fayl: proxy.ts
import { NextResponse, type NextRequest } from "next/server"
import { decrypt, encrypt } from "@/app/lib/session"

const DAY = 24 * 60 * 60

export async function proxy(request: NextRequest) {
  const response = NextResponse.next()
  const session = await decrypt(request.cookies.get("session")?.value)

  // token 1 kundan eski — yangi exp bilan qayta imzolaymiz
  if (session?.iat && Date.now() / 1000 - session.iat > DAY) {
    const expiresAt = new Date(Date.now() + 7 * DAY * 1000)
    const fresh = await encrypt({ userId: session.userId, expiresAt })
    response.cookies.set("session", fresh, {
      httpOnly: true,
      secure: true,
