import "server-only"
import { errors, jwtVerify } from "jose"
import type { SessionPayload } from "@/app/lib/definitions"

const encodedKey = new TextEncoder().encode(process.env.SESSION_SECRET)

export async function decrypt(session: string | undefined) {
  if (!session) return undefined // mehmon — log shart emas
  try {
    const { payload } = await jwtVerify<SessionPayload>(session, encodedKey, {
      algorithms: ["HS256"],
    })
    return payload
  } catch (error) {
    if (error instanceof errors.JWTExpired) console.log("[session] muddati o'tgan")
    else if (error instanceof errors.JWSSignatureVerificationFailed) console.log("[session] imzo soxta")
    else if (error instanceof errors.JOSEError) console.log(`[session] ${error.code}`)
    return undefined
  }
}

