  const [row] = await db
    .insert(sessions)
    .values({ userId, expiresAt, userAgent: (await headers()).get("user-agent") })
    .returning({ id: sessions.id })

  // 2. Sessiya ID'sini imzolash — proxy bazasiz optimistik tekshira oladi
