import "server-only"
import { cache } from "react"
import { cookies } from "next/headers"
import { redirect } from "next/navigation"
import { and, eq, gt } from "drizzle-orm"
import { db } from "@/app/lib/db"
import { sessions, users } from "@/app/lib/schema"
import { decrypt } from "@/app/lib/jwt"

export const verifySession = cache(async () => {
  const token = (await cookies()).get("session")?.value
  const payload = await decrypt(token) // 1. imzo va exp — bazasiz
  if (!payload?.sessionId) redirect("/login")

  // 2. bazada hali bormi va muddati o'tmaganmi
  const [row] = await db
    .select({ userId: sessions.userId, role: users.role })
    .from(sessions)
    .innerJoin(users, eq(users.id, sessions.userId))
    .where(and(eq(sessions.id, payload.sessionId), gt(sessions.expiresAt, new Date())))
  if (!row) redirect("/login")

  return { isAuth: true, sessionId: payload.sessionId, userId: row.userId, role: row.role }
})

// fayl: app/lib/session-token.ts
import "server-only"
import { createHash, randomBytes } from "node:crypto"
import { cookies } from "next/headers"
import { eq } from "drizzle-orm"
import { db } from "@/app/lib/db"
import { sessions } from "@/app/lib/schema"

const sha256 = (token: string) => createHash("sha256").update(token).digest("hex")

export async function createSession(userId: string) {
  const token = randomBytes(32).toString("base64url") // faqat cookie'da
  const expiresAt = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000)
  await db.insert(sessions).values({ tokenHash: sha256(token), userId, expiresAt })

  const cookieStore = await cookies()
  cookieStore.set("sid", token, { httpOnly: true, secure: true, sameSite: "lax", path: "/", expires: expiresAt })
}

export async function validateSession(token: string | undefined) {
  if (!token) return null
  const [row] = await db.select().from(sessions).where(eq(sessions.tokenHash, sha256(token)))
  if (!row || row.expiresAt < new Date()) return null
  return { userId: row.userId, expiresAt: row.expiresAt }
}

