"use server"
import { eq } from "drizzle-orm"
import { revalidatePath } from "next/cache"
import { db } from "@/app/lib/db"
import { recipes } from "@/app/lib/schema"
import { verifySession } from "@/app/lib/dal"

type Result = { error?: string; ok?: boolean }

export async function updateRecipe(id: string, _prev: Result | undefined, formData: FormData): Promise<Result> {
  const session = await verifySession()
  const [recipe] = await db
    .select({ authorId: recipes.authorId })
    .from(recipes)
    .where(eq(recipes.id, id))
  if (!recipe) return { error: "Retsept topilmadi." }

  const isOwner = recipe.authorId === session.userId
  if (!isOwner && session.role !== "admin") {
    return { error: "Bu retsept sizniki emas." }
  }

  const title = String(formData.get("title") ?? "").trim()
  if (title.length < 3) return { error: "Nom kamida 3 harf." }
  await db.update(recipes).set({ title }).where(eq(recipes.id, id))
  revalidatePath(`/recipes/${id}`)
  return { ok: true }
}

