// fayl: app/lib/permissions.ts
export type Role = "admin" | "editor" | "user"
export type Permission = "recipe:create" | "recipe:edit:any" | "recipe:delete" | "comment:moderate" | "user:manage"

const ROLE_PERMISSIONS: Record<Role, Permission[]> = {
  admin: ["recipe:create", "recipe:edit:any", "recipe:delete", "comment:moderate", "user:manage"],
  editor: ["recipe:create", "recipe:edit:any", "comment:moderate"],
  user: ["recipe:create"],
}

export function can(role: Role, permission: Permission) {
  return ROLE_PERMISSIONS[role].includes(permission)
}

