// fayl: app/api/auth/github/callback/route.ts
import { cookies } from "next/headers"
import { redirect } from "next/navigation"
import { upsertGithubUser } from "@/app/lib/users"
import { createSession } from "@/app/lib/session"

export async function GET(request: Request) {
  const { searchParams } = new URL(request.url)
  const code = searchParams.get("code")
  const state = searchParams.get("state")
  const cookieStore = await cookies()
  const savedState = cookieStore.get("oauth_state")?.value
  cookieStore.delete("oauth_state") // bir martalik

  if (!code || !state || state !== savedState) {
    return new Response("Noto'g'ri state", { status: 400 })
  }

  const tokenRes = await fetch("https://github.com/login/oauth/access_token", {
    method: "POST",
    headers: { Accept: "application/json" },
    body: new URLSearchParams({
      client_id: process.env.GITHUB_CLIENT_ID!,
      client_secret: process.env.GITHUB_CLIENT_SECRET!, // faqat serverda
      code,
    }),
  })
  const { access_token } = await tokenRes.json()
  if (!access_token) return new Response("Token olinmadi", { status: 502 })

  const profile = await fetch("https://api.github.com/user", {
    headers: { Authorization: `Bearer ${access_token}` },
  }).then((r) => r.json())

  const user = await upsertGithubUser({ githubId: profile.id, name: profile.name ?? profile.login })
  await createSession(user.id) // provayder tokeni emas, O'Z sessiyamiz
  redirect("/dashboard")
}

