import type { NextRequest } from "next/server"
import { getCurrentUser } from "@/data/auth"
import { updateProfile } from "@/data/profile"

const ALLOWED_ORIGINS = new Set(["https://oshxona.uz"])

export async function POST(request: NextRequest) {
  const origin = request.headers.get("origin")
  if (!origin || !ALLOWED_ORIGINS.has(origin)) {
    return Response.json({ error: "Origin ruxsat etilmagan" }, { status: 403 })
  }

  const user = await getCurrentUser()
  if (!user) return Response.json({ error: "Kirish kerak" }, { status: 401 })

  const body = await request.json()
  await updateProfile(user.id, { bio: String(body.bio ?? "").slice(0, 200) })
  return Response.json({ ok: true })
}

